{
  "type": "sim",
  "engine": "dynamics1d",
  "params": [
    {
      "name": "alpha",
      "label": "学习率 α =",
      "min": 0.01,
      "max": 2.0,
      "step": 0.01,
      "default": 0.9
    }
  ],
  "model": {
    "stateVar": "x",
    "init": -1.5,
    "steps": 30,
    "update": "x - alpha * (2*x)",
    "consts": {}
  },
  "regimes": [
    {
      "when": "alpha >= 1.5",
      "label": "发散",
      "desc": "步长太大，迭代跳出山谷，损失不断增大",
      "tone": "accent"
    },
    {
      "when": "alpha >= 0.3 && alpha < 1.5",
      "label": "震荡收敛",
      "desc": "步长适中，在谷底附近来回震荡但最终收敛",
      "tone": "line"
    },
    {
      "when": "alpha < 0.3",
      "label": "缓慢逼近",
      "desc": "步长太小，每一步只挪动一点，收敛极慢",
      "tone": "ink"
    }
  ],
  "chart": {
    "xLabel": "迭代步数 t",
    "yLabel": "参数 x(t)",
    "targetLine": {
      "value": 0,
      "label": "最优解 x=0"
    }
  }
}
